CHAPTER='Глава 2. Параллельность в пространстве'
def V(label,segments=None,polygon=None,points=None):
    d={'label':label}
    for k,v in [('segments',segments),('polygon',polygon),('points',points)]:
        if v:d[k]=v
    return d

def M(p,e,views=None,planar=False,labels=None,faces=None):
    d={'points':{k:[float(x) for x in v] for k,v in p.items()},'edges':e,'views':{'neutral':V('Данные задачи'),**(views or {})},'labelNames':labels if labels is not None else [k for k in p if not k.startswith('_')]}
    if planar:d['planar']=True
    if faces:d['faces']=faces
    return d

def S(title,q,text,why,view='neutral',kind='theorem'):
    return {'title':title,'prompt':q,'explanation':text,'justifications':[{'kind':kind,'text':why}],'view':view}

def L(sec,n,title,text,goal,m,steps,hint,accepted=None,caption=None,part=None):
    if sec==6: page=55 if n<=7 else 56 if n<=14 else 57 if n<=22 else 58 if n<=29 else 59
    else: page=68 if n<=6 else 69 if n<=13 else 70 if n<=20 else 71 if n<=29 else 72 if n<=38 else 73
    a={'mode':'manual','prompt':'Запиши ответ, построение или доказательство с обоснованием. Запись сохраняется для обсуждения с преподавателем; автоматической оценки доказательства нет.'}
    if accepted:a={'mode':'exact','prompt':goal+' Введи числовой ответ без единиц.','accepted':accepted,'feedback':'Проверь соотношение величин и вычисление в последних шагах.'}
    d={'schemaVersion':1,'revision':1,'id':f'ex-{sec:02}-{n:03}','kind':'exercise','title':f'№ {sec}.{n}. {title}','status':'draft','source':{'bookId':'merzlyak-2022-10-base','collection':'main','exercise':f'{sec}.{n}','chapter':CHAPTER,'printedPages':[page],'pdfPages':[page+1]},'statement':{'text':text,'goal':goal},'visualization':{'type':'scene3d','caption':caption or 'Схема показывает конкретную конфигурацию с выполненными условиями. Доказательство относится ко всем допустимым конфигурациям; длины и углы не измеряют по экрану.','model':m},'help':[{'id':'help-1','question':'Как начать?','text':hint}],'steps':[dict(s,id=f'step-{i+1}') for i,s in enumerate(steps)],'answer':a,'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
    if sec==6 and n==29:
        d['source']['printedPages']=[58,59];d['source']['pdfPages']=[59,60]
    if sec==7 and n in (1,2):
        d['source']['printedPages']=[68,69];d['source']['pdfPages']=[69,70]
    if part is not None:
        d['id']+=f'-{part}';d['source']['subpart']=str(part);d['title']+=f' (пункт {part})'
    assert 3<=len(steps)<=7
