def chain(ns,closed=True):return [[ns[i],ns[(i+1)%len(ns)]] for i in range(len(ns) if closed else len(ns)-1)]
def lerp(a,b,t):return (np.array(a)*(1-t)+np.array(b)*t).tolist()
def cube(a=3,b=None,h=None):
    b=b or a;h=h or a
    p={'A':[0,0,0],'B':[0,b,0],'C':[a,b,0],'D':[a,0,0],'A1':[0,0,h],'B1':[0,b,h],'C1':[a,b,h],'D1':[a,0,h]}
    e=chain(['A','B','C','D'])+chain(['A1','B1','C1','D1'])+[[k,k+'1'] for k in 'ABCD']
    return p,e

def tetra():
    p={'A':[0,0,0],'B':[0,3,0],'C':[4,0,0],'D':[.7,.8,3]}
    return p,chain(['A','B','C'])+[['D',k] for k in 'ABC']

def patch(p,prefix,z=0):
    names=[f'_{prefix}{i}' for i in range(4)]
    for n,x in zip(names,[[-1,-1,z],[4.5,-1,z],[4.5,3.8,z],[-1,3.8,z]]):p[n]=x
    return names

def linepoint(p,a,b,c,d):
    aa=np.array(p[a]);bb=np.array(p[b]);cc=np.array(p[c]);dd=np.array(p[d]);mat=np.column_stack((bb-aa,-(dd-cc)));t=np.linalg.lstsq(mat,cc-aa,rcond=None)[0]
    assert np.linalg.norm(aa+t[0]*(bb-aa)-cc-t[1]*(dd-cc))<1e-7
    return (aa+t[0]*(bb-aa)).tolist()

def section(p,e,three,preferred=None):
    """Exact numeric edge clipping, independently checked by tests."""
    v=[np.array(p[k]) for k in three];normal=np.cross(v[1]-v[0],v[2]-v[0]); assert np.linalg.norm(normal)>1e-8
    hits=[]
    for a,b in e:
        A=np.array(p[a]);B=np.array(p[b]);fa=np.dot(normal,A-v[0]);fb=np.dot(normal,B-v[0])
        if abs(fa)<1e-8: hits.append((a,A))
        if fa*fb< -1e-9:
            X=A+(B-A)*fa/(fa-fb); found=next((k for k,w in p.items() if np.linalg.norm(np.array(w)-X)<1e-7),None)
            if found is None:
                found=(preferred or {}).get(frozenset((a,b))) or f'X{len(hits)+1}'
                p[found]=X.tolist()
            hits.append((found,X))
        if abs(fb)<1e-8:hits.append((b,B))
    uniq={k:v for k,v in hits}; vals=list(uniq.values());center=sum(vals)/len(vals);u=vals[0]-center;u=u/np.linalg.norm(u);w=np.cross(normal/np.linalg.norm(normal),u)
    return sorted(uniq,key=lambda k:math.atan2(np.dot(uniq[k]-center,w),np.dot(uniq[k]-center,u)))

