L(6,9,'Равные треугольники','Треугольник ABC лежит в плоскости α. Через его вершины проведены параллельные прямые, пересекающие параллельную α плоскость β в A₁,B₁,C₁. Докажите равенство ABC и A₁B₁C₁.','Докажи равенство треугольников.',M(p,chain(['A','B','C'])+chain(['A1','B1','C1'])+[[k,k+'1'] for k in 'ABC'],{'ab':V('Параллелограмм ABB₁A₁',polygon=['A','B','B1','A1']),'bc':V('Параллелограмм BCC₁B₁',polygon=['B','C','C1','B1']),'tri':V('Равный образ треугольника',polygon=['A1','B1','C1'])}),[
 S('Первая сторона','Почему AB=A₁B₁?','В плоскости параллельных AA₁,BB₁ следы α и β параллельны: AB∥A₁B₁. Четырёхугольник ABB₁A₁ — параллелограмм, поэтому AB=A₁B₁.','Следы параллельных плоскостей параллельны; противоположные стороны параллелограмма равны.','ab'),S('Оставшиеся стороны','Можно ли повторить рассуждение?','Для BB₁,CC₁ получаем BC=B₁C₁; для CC₁,AA₁ получаем CA=C₁A₁. Все три пары соответственных сторон равны.','То же свойство в двух других секущих плоскостях.','bc'),S('Признак равенства','Какой признак завершает доказательство?','Треугольники ABC и A₁B₁C₁ равны по трём сторонам. При этом наклон проектирующих прямых несущественен.','Признак равенства треугольников по трём сторонам.','tri')], 'Докажи равенство каждой пары сторон через параллелограмм.')
p={'A':[0,0,2],'B':[2,1,2],'C':[4,0,2],'D':[1,0,0],'E':[3,1,0],'F':[3,-1,0]};a=patch(p,'a',2);b=patch(p,'b')
L(6,10,'Следы через заданную точку','Плоскости α и β параллельны. Отрезок AB и точка C лежат в α, точка D — в β (рис. 6.12). Постройте линии пересечения β с плоскостями ABD и BCD.','Построй две прямые в β.',M(p,[['A','B'],['B','C']],{'abd':V('Через D параллельно AB',segments=[['D','E']],polygon=['A','B','D']),'bcd':V('Через D параллельно BC',segments=[['D','F']],polygon=['B','C','D'])},labels=['A','B','C','D'],faces=[b]),[
 S('Известные следы','По каким прямым секущие пересекают α?','ABD∩α=AB, BCD∩α=BC. Точка D не принадлежит α, поэтому секущие отличны от α.','Общая прямая двух плоскостей определяется двумя общими точками.','abd'),S('Первое построение','Как проходит след ABD в β?','Проведём через D в β прямую DE∥AB. Это линия β∩ABD, потому что следы параллельных плоскостей в третьей плоскости параллельны.','Свойство пересечения параллельных плоскостей третьей.','abd'),S('Второе построение','Что изменить для BCD?','Проведём через D в β прямую DF∥BC. Она и есть β∩BCD. Достаточно заданной точки D и направления известного следа.','Через точку проходит единственная прямая, параллельная данной.','bcd')], 'Оба искомых следа проходят через D.')
p={'M':[0,0,2],'N':[3,1,2],'K':[0,1,0],'P':[3,0,0],'E':[3,-1,2],'F':[3,2,0]};a=patch(p,'a',2);b=patch(p,'b')
L(6,11,'Следы в двух плоскостях','Плоскости α и β параллельны. M,N∈α, K,P∈β (рис. 6.13). Постройте линии пересечения α с MKP и β с MNK.','Построй обе линии пересечения.',M(p,[['M','N'],['K','P']],{'first':V('В α: через M параллельно KP',segments=[['M','E']],polygon=['M','K','P']),'second':V('В β: через K параллельно MN',segments=[['K','F']],polygon=['M','N','K'])},labels=['M','N','K','P']),[
 S('Исходные следы','Какие прямые уже известны?','MKP пересекает β по KP; MNK пересекает α по MN. Каждая секущая содержит также заданную точку второй плоскости.','Две общие точки задают общую прямую.','first'),S('След MKP','Как использовать точку M?','В α через M проводим ME∥KP. Это α∩MKP, поскольку следы α и β в MKP параллельны.','Свойство параллельных плоскостей.','first'),S('След MNK','Как использовать точку K?','В β через K проводим KF∥MN. Это β∩MNK. Получены обе искомые прямые.','Через точку проходит единственная прямая данного направления.','second')], 'Для каждой секущей возьми известный след и точку в другой плоскости.')
for part in (1,2):
    if part==1:
        t=36/math.sqrt(2);p={'B':[0,0,0],'A2':[t,0,0],'C2':[0,t,0],'A1':[t*5/9,0,0],'C1':[0,t*5/9,0]}
        given='A₂C₂=36 см и BA₁:BA₂=5:9. Найдите A₁C₁.'
        steps=[S('Параллельные следы','Почему A₁C₁∥A₂C₂?','Это следы параллельных плоскостей в плоскости угла ABC.','Свойство параллельных плоскостей.','far'),S('Подобие','Какое отношение соответственных сторон равно 5:9?','Треугольники BA₁C₁ и BA₂C₂ подобны по двум углам. Поэтому A₁C₁/A₂C₂=BA₁/BA₂=5/9.','Признак подобия по двум углам.','near'),S('Вычисление','Как найти A₁C₁?','A₁C₁=36·5/9=20 см.','Отношение соответственных сторон подобных треугольников.','near')]
        ans=['20'];goal='Найди A₁C₁.'
    else:
        p={'B':[0,0,0],'A1':[0,2*math.sqrt(13),0],'C1':[12,0,0],'A2':[0,3*math.sqrt(13),0],'C2':[18,0,0]}
        given='A₁C₁=14 см, A₂C₂=21 см и BC₁=12 см. Найдите C₁C₂.'
        steps=[S('Подобие треугольников','Почему можно составить пропорцию?','Следы параллельных плоскостей A₁C₁ и A₂C₂ параллельны. Поэтому BA₁C₁ и BA₂C₂ подобны по двум углам.','Свойство параллельных плоскостей и признак подобия.','near'),S('Длина всего лучевого отрезка','Как найти BC₂?','BC₂/BC₁=A₂C₂/A₁C₁=21/14=3/2. Поэтому BC₂=12·3/2=18 см.','Отношение соответственных сторон подобных треугольников.','far'),S('Разность','Почему нужно вычесть BC₁?','C₁ и C₂ лежат на одном луче, а BC₂>BC₁. Поэтому C₁C₂=BC₂−BC₁=18−12=6 см.','Сложение отрезков на одном луче.','far')]
        ans=['6'];goal='Найди C₁C₂.'
    L(6,12,'Подобие на лучах угла','Параллельные плоскости пересекают луч BA в A₁,A₂ и луч BC в C₁,C₂. '+given,goal,M(p,[['B','A2'],['B','C2'],['A1','C1'],['A2','C2']],{'near':V('Ближний треугольник',polygon=['B','A1','C1']),'far':V('Дальний треугольник',polygon=['B','A2','C2'])},planar=True),steps,'Сначала запиши пропорцию для соответствующих сторон подобных треугольников.',accepted=ans,part=part)
