L(6,27,'Сечение параллельно прямой основания','Основание ABCD прямоугольного параллелепипеда и прямая a лежат в плоскости α. E∈AD, F∈CC₁ (рис. 6.20). Постройте сечение, проходящее через E,F параллельно a.','Построй сечение через E,F с заданным направлением.',M(p,e+[ ['U','V'] ],{'base':V('Через E проводим след параллельно a=UV',segments=[['E','P'],['U','V']]),'side':V('Через P,F проходит след правой грани',segments=[['P','F']]),'aux':V('X на продолжении EP; X,S,Q лежат на левом следе',segments=[['E','X'],['X','Q']],points=['X','S','Q']),'section':V('Полученное сечение',polygon=poly)},labels=['A','C','D','E','F','U','V']),[
 S('След в основании','Как использовать направление a?','Через E в основании проводим прямую e∥a. В расположении модели она пересекает CD в P. Прямые e и EF пересекаются в E и определяют единственную секущую плоскость.','Плоскость через две пересекающиеся прямые.','base'),S('Правая грань','Какие точки уже лежат в DCC₁D₁?','P∈CD и F∈CC₁. Проводим PF — след секущей в правой грани. Продолжаем его, если нужно для определения следов соседних граней.','Две точки плоскости определяют содержащуюся в ней прямую.','side'),S('Обход граней','Как получить оставшиеся стороны без произвольных линий?','Продлим e до X= e∩AB. Через X в плоскости ABB₁A₁ проведём прямую, параллельную PF: она пересекает AA₁ в S и A₁B₁ в Q. Через Q в верхней грани проведём прямую, параллельную e, до B₁C₁ в W. Соединяем W с F в задней грани и S с E — в передней.','Следы секущей в противоположных гранях параллельны.','aux'),S('Проверка','Почему плоскость параллельна a?','Она содержит e∥a, а a не лежит в секущей (a и e — разные прямые основания). Поэтому секущая параллельна a. Для положения модели контур — EPFWQS: все стороны соединяют точки одной грани.','Признак параллельности прямой и плоскости.','section')], 'Определи след в основании через E, затем используй вторую данную точку F.',caption='Прямая a обозначена двумя её точками U,V; размеры прямоугольного параллелепипеда выбраны 3×2×2. Конкретный контур зависит от положения E,F и направления a, а метод следов сохраняется.')
p,e=cube(3,2,2);p.update({'E':[0,.5,0],'F':[3,.7,2],'U':[-.5,1.9,0],'V':[1.5,.3,0],'_Edir':[1,-.3,0]});poly=section(p,e,['E','F','_Edir'],{frozenset(('A','D')):'P',frozenset(('B1','C1')):'Q',frozenset(('D','D1')):'R',frozenset(('B','B1')):'S',frozenset(('A1','B1')):'T'})
p['X']=[0,3.1,2]
L(6,28,'Два параллельных следа','Основание ABCD прямоугольного параллелепипеда и прямая a принадлежат α. E∈AB, F∈C₁D₁ (рис. 6.21). Постройте сечение через E,F, параллельное a.','Построй сечение по следам в основаниях.',M(p,e+[ ['U','V'] ],{'base':V('EP∥a в нижней грани',segments=[['E','P'],['U','V']]),'top':V('FQ∥a в верхней грани',segments=[['F','Q']]),'aux':V('X на продолжении FQ, EX — левый след',segments=[['F','X'],['E','X']],points=['X','S']),'section':V('Контур сечения',polygon=poly)},labels=['A','B','C1','D1','E','F','U','V']),[
 S('Нижний след','Как найти вторую точку в основании?','Через E проводим e∥a; в положении модели она пересекает AD в P. Искомая плоскость должна содержать эту прямую.','Плоскость через точку и заданное параллельное направление.','base'),S('Верхний след','Почему его можно провести сразу?','Через F в верхней грани проводим f∥a, значит f∥e. Она пересекает B₁C₁ в Q. Две параллельные прямые e,f определяют плоскость через E,F.','Следы в параллельных основаниях параллельны.','top'),S('Боковые следы','Как получить недостающие вершины?','Продлим e и f до пересечений с плоскостью одной боковой грани, например ABB₁A₁: нижняя точка — E, верхняя — X=f∩A₁B₁ на продолжении. Прямая EX задаёт след этой грани и его точку на BB₁. В противоположной грани через F проводим параллельный след до DD₁. Соединяем соседние точки в передней и задней гранях.','Две общие точки задают след; противоположные грани параллельны.','aux'),S('Проверка','Почему это сечение удовлетворяет задаче?','Все построенные стороны принадлежат плоскости параллельных e,f; она проходит через E,F и содержит направление a. Так как a — другая прямая нижнего основания, плоскость с ней не пересекается. Выделенный многоугольник — её часть внутри параллелепипеда.','Признак параллельности прямой и плоскости.','section')], 'Проведи через E и F две прямые одного направления в параллельных основаниях.')
p,e=cube();p.update({'E':[2.1,0,0],'F':[3,1.65,0],'K':[.75,3,3]});poly=section(p,e,['E','F','K'],{frozenset(('A1','B1')):'P',frozenset(('A','A1')):'Q',frozenset(('D','D1')):'R',frozenset(('C','C1')):'S',frozenset(('A1','D1')):'T'})
p['U']=linepoint(p,'E','F','A','B');p['_Kdir']=(np.array(p['K'])+np.array(p['F'])-p['E']).tolist();p['_V']=linepoint(p,'K','_Kdir','A1','B1')
L(6,29,'Сечение по двум нижним точкам','На рёбрах AD,CD,B₁C₁ куба ABCDA₁B₁C₁D₁ отмечены соответственно E,F,K (рис. 6.22). Постройте сечение плоскостью EFK.','Построй замкнутый контур сечения.',M(p,e,{'bottom':V('Нижний след EF',segments=[['E','F'],['E','U']]),'top':V('Верхний след через K параллельно EF',segments=[['P','K']]),'section':V('Сечение куба',polygon=poly)},labels=['A','D','C','B1','E','F','K']),[
 S('Нижний след','Какая прямая известна сразу?','Прямая EF лежит в основании и в секущей. Её часть EF является нижней стороной сечения.','Две данные точки секущей в одной грани.','bottom'),S('Верхний след','Как использовать K?','Через K в верхней грани проводим прямую, параллельную EF. В положении модели она пересекает A₁B₁ в P; PK — верхняя сторона сечения.','Следы в параллельных гранях параллельны.','top'),S('Одна боковая грань','Как найти точку на AA₁?','Продлим EF до U=EF∩AB. Верхний след пересекает A₁B₁ в P. Прямая UP — след секущей в ABB₁A₁; она пересекает AA₁ в Q. Через F в противоположной грани DCC₁D₁ проводим прямую, параллельную UP, до CC₁ в S.','Метод следов и параллельность противоположных граней.','section'),S('Замыкание','Какие отрезки завершают контур?','Соединяем Q с E в передней грани и S с K в задней. Для показанного расположения сечение — EFSKPQ. Каждая пара соседних вершин лежит в одной грани и в построенной плоскости.','Сечение выпуклого многогранника.','section')], 'Продли нижний след EF до AB; затем свяжи его с верхним следом.')
p,e=cube();p.update({'M':[0,0,.9],'N':[0,1.95,3],'K':[3,1.8,0]});poly=section(p,e,['M','N','K'],{frozenset(('A','D')):'P',frozenset(('C','C1')):'Q',frozenset(('B1','C1')):'R',frozenset(('C1','D1')):'S',frozenset(('D','D1')):'T'})
p['U']=linepoint(p,'M','N','A','B')
L(6,30,'Сечение по следу боковой грани','На рёбрах AA₁,A₁B₁,CD куба ABCDA₁B₁C₁D₁ отмечены M,N,K (рис. 6.23). Постройте сечение плоскостью MNK.','Построй сечение методом следов.',M(p,e,{'left':V('MN и его продолжение до U на AB',segments=[['M','N'],['M','U']]),'bottom':V('Нижний след UK',segments=[['U','K']]),'section':V('Контур сечения',polygon=poly)},labels=['A','B','C','D','M','N','K']),[
 S('Боковой след','Что определяют M и N?','В плоскости ABB₁A₁ проведём MN и продлим до пересечения с прямой AB в U. Точка U лежит в основании и в секущей.','Метод следов: две точки задают прямую секущей.','left'),S('Нижняя и верхняя грани','Как найти следы оснований?','Соединяем U с K. В модели прямая UK пересекает AD в P, поэтому PK — нижняя сторона. Через N в верхней грани проводим прямую, параллельную UK; она пересекает B₁C₁ в R.','Следы в параллельных основаниях параллельны.','bottom'),S('Противоположная боковая грань','Как провести след через K?','В грани DCC₁D₁ через K проводим прямую, параллельную MN. Она пересекает CC₁ в Q. Соединяем Q с R в задней грани, P с M — в передней.','Следы в параллельных боковых гранях параллельны.','section'),S('Проверка','Каков порядок обхода?','Для показанных положений получается шестиугольник MPKQRN. Все его вершины на рёбрах; противоположные следы согласованы по параллельности, поэтому весь контур принадлежит MNK. При ином выборе точек берут фактические выходы тех же следов на рёбра.','Пересечение плоскости с гранями выпуклого куба.','section')], 'Сначала продли MN до плоскости основания.')
p={'A':[0,0,0],'B':[3,0,0],'C':[3,2,0],'D':[1,3,0],'E':[-.5,3,0],'F':[-.5,.25,0]}
L(6,31,'Шесть точек в одной плоскости','Для точек A,B,C,D,E,F известно AB∥DE, BC∥EF, CD∥FA и AB≠DE. Докажите, что все шесть точек лежат в одной плоскости.','Докажи компланарность шести точек.',M(p,chain(list('ABCDEF')),{'pairs':V('Параллельные стороны',segments=[['A','B'],['D','E'],['B','C'],['E','F'],['C','D'],['F','A']]),'plane':V('Плоскость BCD',polygon=['B','C','D'],points=['A','E','F'])},planar=True),[
 S('Вырожденный случай','Что если B,C,D лежат на одной прямой?','Тогда BC и CD имеют одно направление. Из EF∥BC и FA∥CD следует, что E,F,A лежат на одной прямой, параллельной BCD. Две параллельные прямые содержат все шесть точек и лежат в одной плоскости.','Через точку проходит одна прямая данного направления; параллельные прямые компланарны.','pairs'),S('Невырожденный случай','Что если F вне плоскости BCD?','Пусть B,C,D неколлинеарны и β=BCD. Если F∉β, проведём через F плоскость γ∥β. Поскольку FE∥BC и FA∥CD, прямые FE и FA лежат в γ. Значит, A,E,F∈γ.','Свойство прямой через точку плоскости с направлением, параллельным другой параллельной плоскости (задача 6.26).','plane'),S('Противоречие длин','Что отсекают β и γ на AB и DE?','Параллельные прямые AB и DE соединяют две параллельные плоскости γ и β. Следовательно, AB=DE, что противоречит данному неравенству. Поэтому F∈β.','Параллельные плоскости отсекают на параллельных прямых равные отрезки.','pairs'),S('Оставшиеся точки','Почему A и E тоже в β?','Через F∈β прямые FA∥CD и FE∥BC лежат в β. Следовательно, A,E∈β; вместе с B,C,D,F все шесть точек принадлежат одной плоскости.','Прямая через точку плоскости, параллельная прямой этой плоскости, лежит в ней.','plane')], 'Предположи, что плоскости BCD и AFE различны и параллельны; сравни AB и DE.')
p,e=cube();p.update({'M':[.6,0,0],'O':[1.5,1.5,0],'T':[.3,.3,0],'N':[1.2,1.2,1.8],'H':[0,0,-3],'L':[0,0,-.6],'G':[2,2,1]})
L(6,32,'Параллельная прямая и диагональ','Точка M∈AD куба ABCDA₁B₁C₁D₁ делит ребро в отношении AM:MD=1:4. Точка N лежит на диагонали CA₁. Найдите CN:NA₁, если MN∥BC₁D.','Найди отношение CN:NA₁.',M(p,e,{'base':V('T на AC: AT=AC/10',segments=[['M','T'],['B','D'],['A','C']],points=['O']),'diagonal':V('В диагональной плоскости: H,O,C₁ на одной прямой',segments=[['H','C1'],['A1','C']],points=['G']),'parallel':V('LN∥HC₁',segments=[['L','N'],['M','N']],points=['T'])},labels=['A','C','A1','C1','M','N','H','L']),[
 S('Параллельная плоскость через M','Как заменить условие о прямой условием о плоскости?','Проведём через M плоскость σ∥BC₁D. По задаче 6.26 прямая MN лежит в σ. След σ в основании проходит через M параллельно BD. Пусть O=AC∩BD, T=AC∩σ. В треугольнике ADO имеем AT/AO=AM/AD=1/5, поэтому AT/AC=1/10.','Параллельные следы и подобие треугольников.','base'),S('Диагональная плоскость','Где лежит её след с BC₁D?','В плоскости ACC₁A₁ след BC₁D — OC₁. Продлим OC₁ до H на продолжении AA₁ за A. Поскольку AO=OC, подобные прямоугольные треугольники AOH и COC₁ дают AH=CC₁=a; значит A₁H=2a.','Средняя точка диагонали и подобие по двум углам.','diagonal'),S('След σ','Как найти L=σ∩AA₁?','Через T проведём прямую, параллельную HC₁; она пересекает AA₁ в L и CA₁ в N. Подобие ATL и AOH даёт AL/AH=AT/AO=1/5. Поэтому A₁L=a+a/5=6a/5.','Следы параллельных плоскостей в диагональной плоскости параллельны.','parallel'),S('Вспомогательная точка G','В каком отношении HC₁ делит CA₁?','Пусть G=HC₁∩CA₁. Треугольники A₁GH и CGC₁ подобны: A₁H∥CC₁, а две другие пары сторон лежат на общих прямых. Поэтому A₁G/GC=A₁H/CC₁=2, то есть A₁G=(2/3)A₁C.','Подобие треугольников по двум углам.','diagonal'),S('Искомое отношение','Как использовать LN∥HG?','Треугольники A₁LN и A₁HG подобны. A₁N/A₁G=A₁L/A₁H=(6a/5)/(2a)=3/5. Значит A₁N=(3/5)(2/3)A₁C=(2/5)A₁C, а CN=(3/5)A₁C. Ответ: CN:NA₁=3:2.','Подобие и вычитание частей одного отрезка.','parallel')], 'Введи O — центр основания и рассмотри диагональную плоскость ACC₁A₁.')
p={'B1':[0,0,0],'B2':[4,0,0],'B3':[10,0,0],'A1':[0,2,0],'A2':[4,2+2*math.sqrt(5),0],'A3':[10,2+5*math.sqrt(5),0]}
L(6,33,'Параллельные отрезки на рисунке','На рисунке 6.24 A₁B₁∥A₂B₂∥A₃B₃; точки A₁,A₂,A₃ лежат на одной прямой, B₁,B₂,B₃ — на другой, в указанном порядке. B₁B₂=4 см, B₂B₃=6 см, A₁A₃=15 см. Найдите A₁A₂.','Найди A₁A₂.',M(p,[['A1','A3'],['B1','B3']]+[[f'A{i}',f'B{i}'] for i in (1,2,3)],{'ratios':V('Соответствующие части двух секущих',segments=[['A1','A2'],['B1','B2']]),'whole':V('Целые отрезки',segments=[['A1','A3'],['B1','B3']])},planar=True),[
 S('Полный отрезок','Чему равен B₁B₃?','B₂ лежит между B₁ и B₃, поэтому B₁B₃=4+6=10 см.','Сложение отрезков.','whole'),S('Пропорция','Как связаны части на двух секущих?','Параллельные прямые отсекают пропорциональные отрезки: A₁A₂/A₁A₃=B₁B₂/B₁B₃=4/10.','Обобщённая теорема Фалеса.','ratios'),S('Вычисление','Какую долю 15 нужно взять?','A₁A₂=15·4/10=6 см.','Решение пропорции.','ratios')], 'Сначала вычисли B₁B₃, затем сравни часть с целым.',accepted=['6'])
