L(7,6,'Прямая и её параллельный образ','4) Может ли параллельная проекция прямой быть параллельной данной прямой?','Объясни возможность.',M(p,[['A','B']],{'project':V('Проектирование прямой, параллельной плоскости',segments=[['A','A1'],['B','B1']]),'parallel':V('AB∥A₁B₁',segments=[['A','B'],['A1','B1']])}),[
 S('Исходная прямая','Как расположить её относительно плоскости?','Возьмём AB в плоскости z=2, параллельно оси x, и проектируем вертикально на z=0. Исходная прямая параллельна плоскости изображения.','Конкретное допустимое расположение.','project'),S('Образ','Какое направление у A₁B₁?','A₁ и B₁ имеют те же x-координаты, что A и B. Поэтому A₁B₁ тоже направлена вдоль оси x, но лежит на другой высоте.','Определение выбранной параллельной проекции.','parallel'),S('Вывод','Совпадают ли прямые или параллельны?','Они различны и имеют одно направление, следовательно AB∥A₁B₁. Ответ: да.','Определение параллельных прямых.','parallel')], 'Возьми исходную прямую, параллельную плоскости изображения.',part=4)
