L(7,18,'Диаметр, перпендикулярный хорде','Эллипс с центром O₁ и хорда A₁B₁ изображают окружность с центром O и её хорду AB (рис. 7.31). Постройте образ диаметра, перпендикулярного AB. На рисунке хорда не проходит через центр.','Построй образ перпендикулярного диаметра.',M(p,e+[ ['A1','B1'] ],{'mid':V('M₁ — середина хорды',points=['M1'],segments=[['A1','B1']]),'diameter':V('Прямая O₁M₁ пересекает эллипс в P₁,Q₁',segments=[['P1','Q1']])},planar=True,labels=['O1','A1','B1']),[
 S('Исходное свойство','Как провести перпендикуляр к хорде через центр?','Диаметр, проходящий через середину недиаметральной хорды, перпендикулярен ей. Поэтому нужное направление в исходной окружности — OM, где M — середина AB.','Теорема о диаметре и середине хорды.','mid'),S('Построение образа','Как найти M₁?','Отметим середину M₁ отрезка A₁B₁. Так как хорда не проходит через центр, M₁≠O₁. Проводим прямую O₁M₁.','Проекция сохраняет середины и невырожденность данных точек.','diameter'),S('Концы диаметра','Как закончить построение?','Точки P₁,Q₁ пересечения O₁M₁ с эллипсом — образы концов требуемого диаметра. Если бы данная хорда сама была диаметром, приём с её серединой не задал бы направления; этот отдельный случай решается вспомогательной параллельной хордой, как в задаче 7.33.','Образ прямой определяется образами двух её точек.','diameter')], 'Ищи середину хорды, а не перпендикуляр на косом изображении.',caption=ELLIPSE_CAP)
def transform_model(p,e,vertices,mode,center=None,delta=None,labels=None):
    p=copy.deepcopy(p);names={k:k+'r' for k in vertices}
    for k in vertices:p[names[k]]=(2*np.array(center)-p[k] if mode=='reflection' else np.array(p[k])+delta).tolist()
    outedges=[[names[a],names[b]] for a,b in e]
    original=[x for x in vertices if center is None or np.linalg.norm(np.array(p[x])-center)>1e-8][0]
    views={'rule':V('Одинаковое правило для каждой вершины',segments=[[original,names[original]]]),'image':V('Все рёбра образа',segments=outedges)}
    m=M(p,e,views,labels=labels or list(vertices)[:4]);m['labels']={k+'r':k.replace('1','₁')+'′' for k in vertices};return m
for part,centername in [(1,'B1'),(2,'M')]:
    p,e=cube();p['M']=[3,1.2,0];m=transform_model(p,e,list('ABCD')+[x+'1' for x in 'ABCD'],'reflection',center=np.array(p[centername]),labels=['A','B','D',centername]);centertext='вершины B₁' if part==1 else 'точки M∈CD'
    L(7,19,'Центральная симметрия куба',f'В кубе ABCDA₁B₁C₁D₁ на ребре CD отмечена точка M (рис. 7.32). Постройте образ куба при симметрии относительно {centertext}.','Построй образы всех вершин и соедини соответствующие рёбра.',m,[
     S('Центр симметрии','Как определить образ произвольной вершины X?',f'Обозначим центр через S: здесь S={centername.replace("1","₁")}. На прямой XS за S откладываем SX′=SX. Тогда S — середина XX′. Если X=S, образ совпадает с X.','Определение центральной симметрии.','rule'),
     S('Восемь вершин','Как применить правило ко всему кубу?','Строим A′,B′,C′,D′,A₁′,B₁′,C₁′,D₁′ по одному правилу. Для каждой пары проверяем коллинеарность X,S,X′ и равенство SX=SX′.','Определение симметрии относительно точки.','image'),
     S('Рёбра и грани','Какие точки нужно соединить?','Соединяем A′B′C′D′A′ и A₁′B₁′C₁′D₁′A₁′, затем A′A₁′,B′B₁′,C′C₁′,D′D₁′. Это образ всех 12 рёбер; грани ограничены соответствующими четырёхугольниками. Центральная симметрия — движение, поэтому получается равный куб.','Образ отрезка соединяет образы концов; центральная симметрия сохраняет расстояния.','image')], 'Центр должен быть серединой отрезка, соединяющего каждую вершину с её образом.',part=part,caption='Исходные рёбра показаны постоянно; выделение «Все рёбра образа» показывает симметричный куб. Штрих у имени обозначает образ. Вершина, совпадающая с центром симметрии, остаётся на месте.')
