L(7,35,'Биссектриса в прямоугольном треугольнике','Треугольник A₁B₁C₁ изображает прямоугольный ABC с гипотенузой AB. Постройте образ биссектрисы из B, если ∠A=30°.','Построй B₁D₁ с правильным отношением на A₁C₁.',M(p,e,{'ratio':V('A₁D₁:D₁C₁=2:1',segments=[['A1','C1']],points=['D1']),'bisector':V('Образ биссектрисы B₁D₁',segments=[['B1','D1']])},planar=True,labels=['A1','B1','C1']),[
 S('Сторона напротив 30°','Как связаны BC и гипотенуза?','BC лежит напротив угла A=30°, поэтому BC=AB/2. Следовательно, AB:BC=2:1.','Катет напротив угла 30° равен половине гипотенузы.','ratio'),S('Теорема о биссектрисе','Как BD делит AC?','AD:DC=AB:BC=2:1. Поэтому D находится на двух третях отрезка AC от A к C.','Теорема о биссектрисе треугольника.','ratio'),S('Построение изображения','Какое отношение откладывать?','Строим D₁∈A₁C₁ с A₁D₁:D₁C₁=2:1 и соединяем B₁D₁. Это образ биссектрисы; делить угол B₁ пополам на рисунке не требуется.','Проекция сохраняет отношение частей одного отрезка.','bisector')], 'Угол 30° сначала даёт отношение сторон AB:BC.')
