    p,e=ellipse();p.update({'A1':ep(1,0),'B1':ep(-1,0),'J1':ep(0,1),'H1':ep(-.5,0),'P1':ep(-.5,math.sqrt(3)/2),'Q1':ep(-.5,-math.sqrt(3)/2)})
