    steps=[S('Два диаметра','Как выбрать второй диаметр по первому?','Выбираем A₁C₁ через O₁. Строим хорду, параллельную A₁C₁, берём её середину и проводим через неё и O₁ второй диаметр B₁D₁. В исходной окружности AB и другие стороны пока не проведены; сами диаметры AC и BD перпендикулярны.','Построение задачи 7.33: диаметр через середину хорды перпендикулярен её направлению.','diameters'),S('Вписанный квадрат','Почему четырёхугольник из концов диаметров — квадрат?','Соединяем A₁B₁C₁D₁ по порядку на эллипсе. В исходной окружности два перпендикулярных диаметра делят её на четыре равные дуги по 90°. Соответственные хорды равны, а углы четырёхугольника прямые. Следовательно, исходная фигура — квадрат.','Равные дуги стягиваются равными хордами; угол, опирающийся на диаметр, прямой.','square')]
    if part==1:steps.append(S('Проверка изображения','Должны ли его стороны быть равны на экране?','Нет. Достаточно, что вершины являются концами построенных сопряжённых диаметров. Их прообразы образуют квадрат; видимый четырёхугольник обычно является косым параллелограммом.','Параллельная проекция не обязана сохранять равенство отрезков разных направлений.','square'))
    else:steps.append(S('Описанный квадрат','Какие касательные пересечь?','Через A₁,C₁ проводим прямые, параллельные B₁D₁, а через B₁,D₁ — прямые, параллельные A₁C₁. Это образы касательных в концах перпендикулярных диаметров. Их пересечения P₁,Q₁,R₁,S₁ дают образ описанного квадрата: в исходной окружности противоположные стороны параллельны, соседние перпендикулярны, расстояние между противоположными сторонами равно диаметру 2R.','Касательная перпендикулярна радиусу; проекция сохраняет параллельность.','outer'))
    L(7,37,'Квадрат по эллипсу',f'Эллипс с центром O₁ изображает окружность с центром O. Постройте изображение квадрата, {"вписанного в окружность" if part==1 else "описанного около окружности"}.','Построй образ требуемого квадрата.',M(p,e,views,planar=True,labels=['O1']),steps,'Используй два диаметра, которые являются образами взаимно перпендикулярных диаметров окружности.',part=part,caption=ELLIPSE_CAP)
